draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // bird flying
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2 + Math.cos(t) * 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + Math.cos(t) * 20);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.sin(t*2) * 20, H/2 + Math.cos(t) * 20 + Math.cos(t*2) * 10);
  ctx.stroke();

  // fish swimming
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t) * 100, H - 50 + Math.sin(t) * 20, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t) * 100, H - 50 + Math.sin(t) * 20);
  ctx.lineTo(W/2 + Math.cos(t) * 100 + Math.cos(t*2) * 30, H - 50 + Math.sin(t) * 20 + Math.sin(t*2) * 15);
  ctx.stroke();

  ctx.restore();
}
